from pysat.solvers import Glucose4
from pysat.card import CardEnc, EncType
from pysat.formula import IDPool

n = 17
vpool = IDPool()
def E(u,v):
    if u>v: u,v=v,u
    return vpool.id(('e',u,v))

fixed = [(0,15),(3,15),(6,15),(9,15),(11,15),(14,16)]

solver = Glucose4()

# Fixed edges
for (u,v) in fixed:
    solver.add_clause([E(u,v)])

# Triangle-free: for every triple, not all three edges
for i in range(n):
    for j in range(i+1,n):
        for k in range(j+1,n):
            solver.add_clause([-E(i,j),-E(j,k),-E(i,k)])

# Maximal: for every non-edge (u,v), exists w with (u,w) and (v,w)
# i.e., E(u,v) OR exists w: E(u,w) AND E(v,w)
# Equivalent to: E(u,v) OR OR_w (E(u,w) AND E(v,w))
# Use auxiliary vars
for u in range(n):
    for v in range(u+1,n):
        # aux_w means both E(u,w) and E(v,w)
        aux_list = []
        for w in range(n):
            if w==u or w==v: continue
            a = vpool.id(('a',u,v,w))
            # a -> E(u,w), a -> E(v,w)
            solver.add_clause([-a, E(u,w)])
            solver.add_clause([-a, E(v,w)])
            # E(u,w) AND E(v,w) -> a  (only needed one direction for satisfiability)
            solver.add_clause([a, -E(u,w), -E(v,w)])
            aux_list.append(a)
        # E(u,v) OR any aux
        solver.add_clause([E(u,v)] + aux_list)

print("solving...")
res = solver.solve()
print(res)
if res:
    model = set(solver.get_model())
    edges = []
    for i in range(n):
        for j in range(i+1,n):
            if E(i,j) in model:
                edges.append((i,j))
    print(len(edges), edges)
    # verify
    adj = {i:set() for i in range(n)}
    for u,v in edges:
        adj[u].add(v); adj[v].add(u)
    # triangle free
    for i in range(n):
        for j in adj[i]:
            for k in adj[i]:
                if j<k and k in adj[j]:
                    print("TRIANGLE",i,j,k)
    # maximal
    for i in range(n):
        for j in range(i+1,n):
            if j not in adj[i]:
                if not (adj[i] & adj[j]):
                    print("NOT MAXIMAL",i,j)
    print("verified")
